+fn run_with_args(bin: &str, args: &[String]) -> i32 {
+    let mut state = GlobalState::default();
+    let mut index = 0usize;
+    let mut explicit_end = false;
+
+    while index < args.len() {
+        if args[index] == "--" {
+            explicit_end = true;
