+        },
+    };
+
+    if config.scripts.contains_key(&alias) && !force {
+        return fail(CliError::new(format!("AliasAlreadyExists:  {}", alias)));
+    }
+
+    let script = Script {
+        command,
+        description,
+        tags: if tags_seen { Some(tags) } else { None },
+    };
+
+    config.scripts.insert(alias.clone(), script);
+    if let Err(error) = write_config(&config_path, &config) {
+        return fail(error);
+    }
+
+    println!("Added {}", alias);
+    0
+}
+
+fn run_config_init(bin: &str, global: &GlobalOptions, args: &[String]) -> i32 {
+    let mut index = 0usize;
+    while index < args.len() {
+        let current = &args[index];
+        match current.as_str() {
+            "-h" | "--help" => {
+                print_config_init_help(bin);
+                return 0;
+            }
+            "-V" | "--version" => {
+                print_subcommand_version(bin, "config-init");
+                return 0;
+            }
+            _ => {
+                return parse_error(
+                    &format!(
+                        "Found argument '{}' which wasn't expected, or isn't valid in this context",
+                        current
+                    ),
+                    &format!("    {} config-init", bin),
+                )
+            }
+        }
+    }
+
+    let path = resolve_init_path(global);
+    if path.exists() {
+        return fail(CliError::new(format!(
+            "Cannot initialize config at {}, file already exists.",
+            path.display()
+        )));
+    }
+
+    if let Some(parent) = path.parent() {
+        match fs::create_dir(parent) {
+            Ok(_) => {}
+            Err(error) if error.kind() == io::ErrorKind::AlreadyExists => {}
+            Err(error) => {
+                return fail(CliError::new(format!(
+                    "Failed to create directory. {}",
+                    error
+                )))
+            }
+        }
+    }
+
+    let mut config = Config::default();
+    config.scripts.insert(
+        "hello-pier".to_string(),
+        Script {
+            command: "echo Hello, Pier!".to_string(),
+            description: Some("This is an example command.".to_string()),
+            tags: None,
+        },
+    );
+
+    if let Err(error) = write_config(&path, &config) {
+        return fail(error);
+    }
+
+    println!("Added hello-pier");
+    0
+}
+
+fn run_copy(bin: &str, global: &GlobalOptions, args: &[String]) -> i32 {
+    let mut index = 0usize;
+    let mut positional = Vec::new();
+
+    while index < args.len() {
+        let current = &args[index];
+        match current.as_str() {
+            "-h" | "--help" => {
+                print_copy_help(bin);
+                return 0;
+            }
+            "-V" | "--version" => {
+                print_subcommand_version(bin, "copy");
+                return 0;
+            }
+            _ if current.starts_with('-') && current != "-" => {
+                return parse_error(
+                    &format!(
+                        "Found argument '{}' which wasn't expected, or isn't valid in this context",
+                        current
+                    ),
+                    &format!("    {} copy <from-alias> <to-alias>", bin),
+                )
+            }
+            _ => {
+                positional.push(current.clone());
+                index += 1;
+            }
+        }
+    }
+
+    if positional.len() < 2 {
+        let mut missing = Vec::new();
+        if positional.is_empty() {
+            missing.push("<from-alias>");
+            missing.push("<to-alias>");
+        } else {
+            missing.push("<to-alias>");
+        }
+        return missing_required_error(
+            &missing,
+            &format!("    {} copy <from-alias> <to-alias>", bin),
+        );
+    }
+    if positional.len() > 2 {
+        return parse_error(
+            &format!(
+                "Found argument '{}' which wasn't expected, or isn't valid in this context",
+                positional[2]
+            ),
+            &format!("    {} copy <from-alias> <to-alias>", bin),
+        );
+    }
+
+    let config_path = match resolve_read_path(global) {
+        Ok(path) => path,
+        Err(error) => return fail(error),
+    };
+    let mut config = match read_config(&config_path) {
+        Ok(config) => config,
+        Err(error) => return fail(error),
+    };
+
+    let from_alias = &positional[0];
+    let to_alias = &positional[1];
+    let script = match config.scripts.get(from_alias) {
+        Some(script) => script.clone(),
+        None => {
+            return fail(CliError::new(format!(
+                "AliasNotFound: No script found by alias {}",
+                from_alias
+            )))
+        }
+    };
+
+    if config.scripts.contains_key(to_alias) {
+        return fail(CliError::new(format!("AliasAlreadyExists:  {}", to_alias)));
+    }
+
+    config.scripts.insert(to_alias.clone(), script);
+    if let Err(error) = write_config(&config_path, &config) {
+        return fail(error);
+    }
+
+    println!("Copy from alias {} to new alias {}", from_alias, to_alias);
+    0
+}
+
+fn run_edit(bin: &str, global: &GlobalOptions, args: &[String]) -> i32 {
+    let alias = match parse_single_alias_subcommand(bin, "edit", args) {
+        Ok(ControlAlias::Help) => {
+            print_edit_help(bin);
+            return 0;
+        }
+        Ok(ControlAlias::Version) => {
+            print_subcommand_version(bin, "edit");
+            return 0;
+        }
+        Ok(ControlAlias::Alias(alias)) => alias,
+        Err(code) => return code,
+    };
+
+    let config_path = match resolve_read_path(global) {
+        Ok(path) => path,
+        Err(error) => return fail(error),
+    };
+    let mut config = match read_config(&config_path) {
+        Ok(config) => config,
+        Err(error) => return fail(error),
+    };
+
+    let current = match lookup_script_with_empty_message_mut(&mut config, &alias) {
+        Ok(script) => script,
+        Err(error) => return fail(error),
+    };
+
+    let updated = match open_editor(current.command.clone()) {
+        Ok(command) => command,
+        Err(error) => return fail(CliError::new(error)),
+    };
+    current.command = updated;
+
+    if let Err(error) = write_config(&config_path, &config) {
+        return fail(error);
+    }
+
+    println!("Edited {}", alias);
+    0
+}
+
+fn run_help(bin: &str, args: &[String]) -> i32 {
+    if args.is_empty() {
+        print_top_help_short(bin);
+        return 0;
+    }
+
+    if args.len() > 1 {
+        return help_unknown_subcommand_error(bin, &args[args.len() - 1]);
+    }
+
+    let target = &args[0];
+    match target.as_str() {
+        "add" => print_add_help(bin),
+        "config-init" | "init" => print_config_init_help(bin),
+        "copy" | "cp" => print_copy_help(bin),
+        "edit" => print_edit_help(bin),
+        "help" => print_help_help(bin),
+        "list" | "ls" => print_list_help(bin),
+        "move" | "mv" | "rename" => print_move_help(bin),
+        "remove" | "rm" => print_remove_help(bin),
+        "run" => print_run_help(bin),
+        "show" => print_show_help(bin),
+        _ => return help_unknown_subcommand_error(bin, target),
+    }
+    0
+}
+
+fn run_list(bin: &str, global: &GlobalOptions, args: &[String]) -> i32 {
+    let mut list_aliases = false;
+    let mut full_command = false;
+    let mut cmd_width: Option<usize> = None;
+    let mut tags = Vec::new();
+    let mut tags_seen = false;
+    let mut index = 0usize;
+
+    while index < args.len() {
+        let current = &args[index];
+        match current.as_str() {
+            "-h" | "--help" => {
+                print_list_help(bin);
+                return 0;
+            }
+            "-V" | "--version" => {
+                print_subcommand_version(bin, "list");
+                return 0;
+            }
+            "-q" | "--list_aliases" => {
+                list_aliases = true;
+                index += 1;
+            }
+            "-l" | "--cmd_full" => {
+                full_command = true;
+                index += 1;
+            }
+            "-c" | "--cmd_width" => {
+                if index + 1 >= args.len() {
+                    return parse_error(
+                        "The argument '--cmd_width <cmd-width>' requires a value but none was supplied",
+                        &format!("    {} list [FLAGS] [OPTIONS]", bin),
+                    );
+                }
+                match args[index + 1].parse::<usize>() {
+                    Ok(value) => cmd_width = Some(value),
+                    Err(_) => {
+                        return parse_error(
+                            &format!(
+                                "Invalid value '{}' for '--cmd_width <cmd-width>'",
+                                args[index + 1]
+                            ),
+                            &format!("    {} list [FLAGS] [OPTIONS]", bin),
+                        )
+                    }
+                }
+                index += 2;
+            }
+            "-t" | "--tag" => {
+                tags_seen = true;
+                index += 1;
+                while index < args.len() {
+                    let next = &args[index];
+                    if next == "--" {
+                        break;
+                    }
+                    if next.starts_with('-') && next != "-" {
+                        break;
+                    }
+                    tags.push(next.clone());
+                    index += 1;
+                }
+            }
+            _ if current.starts_with("--cmd_width=") => {
+                let raw = &current["--cmd_width=".len()..];
+                match raw.parse::<usize>() {
+                    Ok(value) => cmd_width = Some(value),
+                    Err(_) => {
+                        return parse_error(
+                            &format!("Invalid value '{}' for '--cmd_width <cmd-width>'", raw),
+                            &format!("    {} list [FLAGS] [OPTIONS]", bin),
+                        )
+                    }
+                }
+                index += 1;
+            }
+            _ if current.starts_with("--tag=") => {
+                tags_seen = true;
+                let value = current["--tag=".len()..].to_string();
+                if !value.is_empty() {
+                    tags.push(value);
+                }
+                index += 1;
+                while index < args.len() {
+                    let next = &args[index];
+                    if next == "--" {
+                        break;
+                    }
+                    if next.starts_with('-') && next != "-" {
+                        break;
+                    }
+                    tags.push(next.clone());
+                    index += 1;
+                }
+            }
+            _ if current.starts_with('-') && current != "-" => {
+                return parse_error(
+                    &format!(
+                        "Found argument '{}' which wasn't expected, or isn't valid in this context",
+                        current
+                    ),
+                    &format!("    {} list [FLAGS] [OPTIONS]", bin),
+                )
+            }
+            _ => {
+                return parse_error(
+                    &format!(
+                        "Found argument '{}' which wasn't expected, or isn't valid in this context",
+                        current
+                    ),
+                    &format!("    {} list [FLAGS] [OPTIONS]", bin),
+                )
+            }
+        }
+    }
+
+    let config_path = match resolve_read_path(global) {
+        Ok(path) => path,
+        Err(error) => return fail(error),
+    };
+    let config = match read_config(&config_path) {
+        Ok(config) => config,
+        Err(error) => return fail(error),
+    };
+
+    if config.scripts.is_empty() {
+        return fail(CliError::new(
+            "No scripts exist. Would you like to add a new script?",
+        ));
+    }
+
+    let scripts = collect_scripts_for_list(&config, if tags_seen { Some(&tags) } else { None });
+    if list_aliases {
+        for (alias, _) in scripts {
+            println!("{}", alias);
+        }
+        return 0;
+    }
+
+    let table = render_list_table(
+        scripts,
+        if full_command {
+            CommandDisplay::Full
+        } else {
+            CommandDisplay::Truncated(cmd_width.unwrap_or(DEFAULT_CMD_WIDTH))
+        },
+    );
+    print!("{}", table);
+    0
+}
