+fn run_run(bin: &str, global: &GlobalOptions, args: &[String]) -> i32 {
+    let (alias, forwarded) = match parse_run_like_subcommand(bin, "run", args) {
+        Ok(ControlRun::Help) => {
+            print_run_help(bin);
+            return 0;
+        }
+        Ok(ControlRun::Version) => {
+            print_subcommand_version(bin, "run");
+            return 0;
+        }
+        Ok(ControlRun::Alias(alias, forwarded)) => (alias, forwarded),
+        Err(code) => return code,
+    };
+
+    let config_path = match resolve_read_path(global) {
+        Ok(path) => path,
+        Err(error) => return fail(error),
+    };
+    let config = match read_config(&config_path) {
+        Ok(config) => config,
+        Err(error) => return fail(error),
+    };
+
+    let script = match lookup_script_with_empty_message(&config, &alias) {
+        Ok(script) => script,
+        Err(error) => return fail(error),
+    };
+
+    run_script(&alias, script, &forwarded, global.verbose)
+}
