+fn parse_single_alias_subcommand(
+    bin: &str,
+    command: &str,
+    args: &[String],
+) -> Result<ControlAlias, i32> {
+    let mut positional = Vec::new();
+    for current in args {
+        match current.as_str() {
+            "-h" | "--help" => return Ok(ControlAlias::Help),
+            "-V" | "--version" => return Ok(ControlAlias::Version),
+            _ if current.starts_with('-') && current != "-" => {
+                return Err(parse_error(
+                    &format!(
+                        "Found argument '{}' which wasn't expected, or isn't valid in this context",
+                        current
+                    ),
+                    &format!("    {} {} <alias>", bin, command),
+                ))
+            }
+            _ => positional.push(current.clone()),
+        }
+    }
+
+    if positional.is_empty() {
+        return Err(missing_required_error(
+            &["<alias>"],
+            &format!("    {} {} <alias>", bin, command),
+        ));
+    }
+    if positional.len() > 1 {
+        return Err(parse_error(
+            &format!(
+                "Found argument '{}' which wasn't expected, or isn't valid in this context",
+                positional[1]
+            ),
+            &format!("    {} {} <alias>", bin, command),
+        ));
+    }
+
+    Ok(ControlAlias::Alias(positional.remove(0)))
+}
+
+fn parse_run_like_subcommand(
+    bin: &str,
+    command: &str,
+    args: &[String],
+) -> Result<ControlRun, i32> {
+    let mut index = 0usize;
+    let mut positional = Vec::new();
+    let mut raw_mode = false;
+
+    while index < args.len() {
+        let current = &args[index];
+        if !raw_mode && current == "--" {
+            raw_mode = true;
+            index += 1;
+            continue;
+        }
+
+        if !raw_mode {
+            match current.as_str() {
+                "-h" | "--help" => return Ok(ControlRun::Help),
+                "-V" | "--version" => return Ok(ControlRun::Version),
+                _ if current.starts_with('-') && current != "-" => {
+                    return Err(parse_error(
+                        &format!(
+                            "Found argument '{}' which wasn't expected, or isn't valid in this context",
+                            current
+                        ),
+                        &format!("    {} {} <alias> [args]...", bin, command),
+                    ))
+                }
+                _ => {}
+            }
+        }
+
+        positional.push(current.clone());
+        index += 1;
+    }
+
+    if positional.is_empty() {
+        return Err(missing_required_error(
+            &["<alias>"],
+            &format!("    {} {} <alias> [args]...", bin, command),
+        ));
+    }
+
+    let alias = positional.remove(0);
+    if positional.first().map(String::as_str) == Some("--") {
+        positional.remove(0);
+    }
+
+    Ok(ControlRun::Alias(alias, positional))
+}
