+fn resolve_read_path(global: &GlobalOptions) -> Result<PathBuf, CliError> {
+    if let Some(path) = &global.config_path {
+        return Ok(PathBuf::from(path));
+    }
+
+    if let Some(path) = env::var_os("PIER_CONFIG_PATH") {
+        return Ok(PathBuf::from(path));
+    }
+
+    let local = PathBuf::from("pier.toml");
+    if local.exists() {
+        return Ok(local);
+    }
+
+    let mut candidates = Vec::new();
+    if let Some(config_home) = config_home_dir() {
+        candidates.push(config_home.join("pier").join("config.toml"));
+        candidates.push(config_home.join("pier").join("config"));
+        candidates.push(config_home.join("pier.toml"));
+    }
+    if let Some(home) = home_dir() {
+        candidates.push(home.join(".pier.toml"));
+        candidates.push(home.join(".pier"));
+    }
+
+    for candidate in candidates {
+        if candidate.exists() {
+            return Ok(candidate);
+        }
+    }
+
+    Err(CliError::new(
+        "No default config file found. See help for more info.",
+    ))
+}
+
+fn resolve_init_path(global: &GlobalOptions) -> PathBuf {
+    if let Some(path) = &global.config_path {
+        return PathBuf::from(path);
+    }
+
+    match config_home_dir() {
+        Some(path) => path.join("pier").join("config.toml"),
+        None => PathBuf::from(""),
+    }
+}
