+fn read_config(path: &Path) -> Result<Config, CliError> {
+    let raw = fs::read_to_string(path).map_err(|error| {
+        CliError::new(format!(
+            "Unable to read config from file {}: {} ",
+            path.display(),
+            error
+        ))
+    })?;
+
+    toml::from_str::<Config>(&raw).map_err(|error| {
+        CliError::new(format!(
+            "Unable to parse toml config from file {}: {}",
+            path.display(),
+            error
+        ))
+    })
+}
+
+fn write_config(path: &Path, config: &Config) -> Result<(), CliError> {
+    let raw = toml::to_string_pretty(config)
+        .map_err(|error| CliError::new(format!("Unable to serialize config: {}", error)))?;
+    fs::write(path, raw)
+        .map_err(|error| CliError::new(format!("Unable to write config to file {}: {}", path.display(), error)))
+}
