+fn run_script(alias: &str, script: &Script, args: &[String], verbose: bool) -> i32 {
+    if verbose {
+        println!("Starting script \"{}\"", alias);
+        println!("{}", RULE);
+    }
+
+    let mut command = Command::new("sh");
+    command
+        .arg("-c")
+        .arg(&script.command)
+        .arg(alias)
+        .args(args)
+        .stdin(Stdio::inherit())
+        .stdout(Stdio::inherit())
+        .stderr(Stdio::inherit());
+
+    let status = match command.status() {
+        Ok(status) => status,
+        Err(error) => {
+            return fail(CliError::new(format!(
+                "Failed to run script {}: {}",
+                alias, error
+            )))
+        }
+    };
+
+    if verbose {
+        println!("{}", RULE);
+        println!("Script complete");
+    }
+
+    status.code().unwrap_or(1)
+}
