use serde::{Deserialize, Serialize};
use std::cmp::Ordering;
use std::collections::BTreeMap;
use std::env;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::process::{self, Command, Stdio};
use std::sync::atomic::{AtomicU64, Ordering as AtomicOrdering};
use std::time::{SystemTime, UNIX_EPOCH};

const VERSION: &str = "0.1.6";
const APP_NAME: &str = "pier";
const AUTHORS: &str = "Benjamin Scholtz, Isak Johansson";
const ABOUT: &str = "A simple script management CLI";
const RULE: &str = "-------------------------";
const TABLE_RULE: char = '≖';
const TABLE_SEP: char = '⋮';
const DEFAULT_CMD_WIDTH: usize = 80;

static TEMP_COUNTER: AtomicU64 = AtomicU64::new(0);

#[derive(Debug, Clone, Default)]
struct GlobalOptions {
    config_path: Option<String>,
    config_from_cli: bool,
    verbose: bool,
}

#[derive(Debug, Default)]
struct GlobalState {
    global: GlobalOptions,
    repeated_config: bool,
    repeated_verbose: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct Config {
    #[serde(default)]
    scripts: BTreeMap<String, Script>,
    #[serde(default)]
    default: BTreeMap<String, toml::Value>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Script {
    command: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    description: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    tags: Option<Vec<String>>,
}

#[derive(Debug)]
struct CliError {
    message: String,
}

impl CliError {
    fn new(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Subcommand {
    Add,
    ConfigInit,
    Copy,
    Edit,
    Help,
    List,
    Move,
    Remove,
    Run,
    Show,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum GlobalToken {
    Help,
    Version,
    NotGlobal,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum ParseStep {
    Consumed(usize),
    Signal(GlobalToken),
    UnknownOption(String),
    MissingValue(String),
}

fn main() {
    process::exit(run());
}

fn run() -> i32 {
    let args: Vec<String> = env::args().collect();
    let bin = bin_name(&args);
    run_with_args(&bin, &args[1..])
}

fn run_with_args(bin: &str, args: &[String]) -> i32 {
    let mut state = GlobalState::default();
    let mut index = 0usize;
    let mut explicit_end = false;

    while index < args.len() {
        if args[index] == "--" {
            explicit_end = true;
            index += 1;
            break;
        }

        match parse_global_step(&args[index..], &mut state, false) {
            ParseStep::Consumed(consumed) => index += consumed,
            ParseStep::Signal(GlobalToken::Help) => {
                print_top_help_long(bin);
                return 0;
            }
            ParseStep::Signal(GlobalToken::Version) => {
                print_top_version();
                return 0;
            }
            ParseStep::Signal(GlobalToken::NotGlobal) => break,
            ParseStep::UnknownOption(option) => {
                return parse_error(
                    &format!(
                        "Found argument '{}' which wasn't expected, or isn't valid in this context",
                        option
                    ),
                    &top_usage_for_flags(bin, &state.global),
                );
            }
            ParseStep::MissingValue(flag) => {
                return parse_error(
                    &format!(
                        "The argument '{}' requires a value but none was supplied",
                        flag
                    ),
                    &top_usage_for_flags(bin, &state.global),
                );
            }
        }
    }

    if index >= args.len() {
        return missing_required_error(
            &["<alias>"],
            &top_usage_for_flags(bin, &state.global),
        );
    }

    let first = args[index].clone();
    index += 1;

    if state.repeated_config {
        return repeated_config_error(bin, &state.global);
    }
    if state.repeated_verbose {
        return repeated_verbose_error(bin, &state.global);
    }

    if !explicit_end {
        if let Some(subcommand) = subcommand_from_name(&first) {
            return dispatch_subcommand(bin, &state.global, subcommand, &args[index..]);
        }
    }

    if let Some(suggestion) = subcommand_suggestion(&first, explicit_end) {
        return unknown_subcommand_error(bin, &state.global, &first, Some(&suggestion));
    }

    run_alias_path(bin, state, first, &args[index..])
}

fn run_alias_path(bin: &str, mut state: GlobalState, alias: String, tail: &[String]) -> i32 {
    let mut script_args = Vec::new();
    let mut index = 0usize;
    let mut raw_mode = false;

    while index < tail.len() {
        if raw_mode {
            script_args.extend_from_slice(&tail[index..]);
            break;
        }

        if script_args.is_empty() {
            if tail[index] == "--" {
                raw_mode = true;
                index += 1;
                continue;
            }

            match parse_global_step(&tail[index..], &mut state, true) {
                ParseStep::Consumed(consumed) => {
                    index += consumed;
                    continue;
                }
                ParseStep::Signal(GlobalToken::Help) => {
                    print_top_help_long(bin);
                    return 0;
                }
                ParseStep::Signal(GlobalToken::Version) => {
                    print_top_version();
                    return 0;
                }
                ParseStep::Signal(GlobalToken::NotGlobal) => {
                    script_args.push(tail[index].clone());
                    index += 1;
                    script_args.extend_from_slice(&tail[index..]);
                    break;
                }
                ParseStep::UnknownOption(option) => {
                    return parse_error(
                        &format!(
                            "Found argument '{}' which wasn't expected, or isn't valid in this context",
                            option
                        ),
                        &top_usage_for_flags(bin, &state.global),
                    );
                }
                ParseStep::MissingValue(flag) => {
                    return parse_error(
                        &format!(
                            "The argument '{}' requires a value but none was supplied",
                            flag
                        ),
                        &top_usage_for_flags(bin, &state.global),
                    );
                }
            }
        } else {
            script_args.extend_from_slice(&tail[index..]);
            break;
        }
    }

    if state.repeated_config {
        return repeated_config_error(bin, &state.global);
    }
    if state.repeated_verbose {
        return repeated_verbose_error(bin, &state.global);
    }

    let config_path = match resolve_read_path(&state.global) {
        Ok(path) => path,
        Err(error) => return fail(error),
    };
    let config = match read_config(&config_path) {
        Ok(config) => config,
        Err(error) => return fail(error),
    };

    let script = match lookup_script_with_empty_message(&config, &alias) {
        Ok(script) => script,
        Err(error) => return fail(error),
    };

    run_script(&alias, script, &script_args, state.global.verbose)
}

fn dispatch_subcommand(bin: &str, global: &GlobalOptions, subcommand: Subcommand, args: &[String]) -> i32 {
    match subcommand {
        Subcommand::Add => run_add(bin, global, args),
        Subcommand::ConfigInit => run_config_init(bin, global, args),
        Subcommand::Copy => run_copy(bin, global, args),
        Subcommand::Edit => run_edit(bin, global, args),
        Subcommand::Help => run_help(bin, args),
        Subcommand::List => run_list(bin, global, args),
        Subcommand::Move => run_move(bin, global, args),
        Subcommand::Remove => run_remove(bin, global, args),
        Subcommand::Run => run_run(bin, global, args),
        Subcommand::Show => run_show(bin, global, args),
    }
}

fn run_add(bin: &str, global: &GlobalOptions, args: &[String]) -> i32 {
    let mut alias: Option<String> = None;
    let mut description: Option<String> = None;
    let mut tags: Vec<String> = Vec::new();
    let mut tags_seen = false;
    let mut force = false;
    let mut command: Option<String> = None;
    let mut index = 0usize;
    let mut positional_only = false;

    while index < args.len() {
        let current = &args[index];
        if !positional_only && current == "--" {
            positional_only = true;
            index += 1;
            continue;
        }

        if !positional_only {
            match current.as_str() {
                "-h" | "--help" => {
                    print_add_help(bin);
                    return 0;
                }
                "-V" | "--version" => {
                    print_subcommand_version(bin, "add");
                    return 0;
                }
                "-f" | "--force" => {
                    force = true;
                    index += 1;
                    continue;
                }
                "-a" | "--alias" => {
                    if index + 1 >= args.len() {
                        return parse_error(
                            "The argument '--alias <alias>' requires a value but none was supplied",
                            &format!("    {} add [FLAGS] [OPTIONS] --alias <alias> [--] [command]", bin),
                        );
                    }
                    alias = Some(args[index + 1].clone());
                    index += 2;
                    continue;
                }
                "-d" | "--description" => {
                    if index + 1 >= args.len() {
                        return parse_error(
                            "The argument '--description <description>' requires a value but none was supplied",
                            &format!("    {} add [FLAGS] [OPTIONS] --alias <alias> [--] [command]", bin),
                        );
                    }
                    description = Some(args[index + 1].clone());
                    index += 2;
                    continue;
                }
                "-t" | "--tag" => {
                    tags_seen = true;
                    index += 1;
                    while index < args.len() {
                        let next = &args[index];
                        if next == "--" {
                            break;
                        }
                        if next.starts_with('-') && next != "-" {
                            break;
                        }
                        tags.push(next.clone());
                        index += 1;
                    }
                    continue;
                }
                _ => {}
            }

            if current.starts_with("--alias=") {
                alias = Some(current["--alias=".len()..].to_string());
                index += 1;
                continue;
            }
            if current.starts_with("--description=") {
                description = Some(current["--description=".len()..].to_string());
                index += 1;
                continue;
            }
            if current.starts_with("--tag=") {
                tags_seen = true;
                let value = current["--tag=".len()..].to_string();
                if !value.is_empty() {
                    tags.push(value);
                }
                index += 1;
                while index < args.len() {
                    let next = &args[index];
                    if next == "--" {
                        break;
                    }
                    if next.starts_with('-') && next != "-" {
                        break;
                    }
                    tags.push(next.clone());
                    index += 1;
                }
                continue;
            }
            if current.starts_with('-') && current != "-" {
                return parse_error(
                    &format!(
                        "Found argument '{}' which wasn't expected, or isn't valid in this context",
                        current
                    ),
                    &format!("    {} add [FLAGS] [OPTIONS] --alias <alias> [--] [command]", bin),
                );
            }
        }

        if command.is_none() {
            command = Some(current.clone());
            index += 1;
            continue;
        }

        return parse_error(
            &format!(
                "Found argument '{}' which wasn't expected, or isn't valid in this context",
                current
            ),
            &format!("    {} add [FLAGS] [OPTIONS] --alias <alias> [--] [command]", bin),
        );
    }

    let alias = match alias {
        Some(alias) => alias,
        None => {
            return missing_required_error(
                &["--alias <alias>"],
                &format!("    {} add [FLAGS] [OPTIONS] --alias <alias> [--] [command]", bin),
            )
        }
    };

    let config_path = match resolve_read_path(global) {
        Ok(path) => path,
        Err(error) => return fail(error),
    };
    let mut config = match read_config(&config_path) {
        Ok(config) => config,
        Err(error) => return fail(error),
    };

    let command = match command {
        Some(command) => command,
        None => match open_editor("".to_string()) {
            Ok(command) => command,
            Err(error) => return fail(CliError::new(error)),
        },
    };

    if config.scripts.contains_key(&alias) && !force {
        return fail(CliError::new(format!("AliasAlreadyExists:  {}", alias)));
    }

    let script = Script {
        command,
        description,
        tags: if tags_seen { Some(tags) } else { None },
    };

    config.scripts.insert(alias.clone(), script);
    if let Err(error) = write_config(&config_path, &config) {
        return fail(error);
    }

    println!("Added {}", alias);
    0
}

fn run_config_init(bin: &str, global: &GlobalOptions, args: &[String]) -> i32 {
    let mut index = 0usize;
    while index < args.len() {
        let current = &args[index];
        match current.as_str() {
            "-h" | "--help" => {
                print_config_init_help(bin);
                return 0;
            }
            "-V" | "--version" => {
                print_subcommand_version(bin, "config-init");
                return 0;
            }
            _ => {
                return parse_error(
                    &format!(
                        "Found argument '{}' which wasn't expected, or isn't valid in this context",
                        current
                    ),
                    &format!("    {} config-init", bin),
                )
            }
        }
    }

    let path = resolve_init_path(global);
    if path.exists() {
        return fail(CliError::new(format!(
            "Cannot initialize config at {}, file already exists.",
            path.display()
        )));
    }

    if let Some(parent) = path.parent() {
        match fs::create_dir(parent) {
            Ok(_) => {}
            Err(error) if error.kind() == io::ErrorKind::AlreadyExists => {}
            Err(error) => {
                return fail(CliError::new(format!(
                    "Failed to create directory. {}",
                    error
                )))
            }
        }
    }

    let mut config = Config::default();
    config.scripts.insert(
        "hello-pier".to_string(),
        Script {
            command: "echo Hello, Pier!".to_string(),
            description: Some("This is an example command.".to_string()),
            tags: None,
        },
    );

    if let Err(error) = write_config(&path, &config) {
        return fail(error);
    }

    println!("Added hello-pier");
    0
}

fn run_copy(bin: &str, global: &GlobalOptions, args: &[String]) -> i32 {
    let mut index = 0usize;
    let mut positional = Vec::new();

    while index < args.len() {
        let current = &args[index];
        match current.as_str() {
            "-h" | "--help" => {
                print_copy_help(bin);
                return 0;
            }
            "-V" | "--version" => {
                print_subcommand_version(bin, "copy");
                return 0;
            }
            _ if current.starts_with('-') && current != "-" => {
                return parse_error(
                    &format!(
                        "Found argument '{}' which wasn't expected, or isn't valid in this context",
                        current
                    ),
                    &format!("    {} copy <from-alias> <to-alias>", bin),
                )
            }
            _ => {
                positional.push(current.clone());
                index += 1;
            }
        }
    }

    if positional.len() < 2 {
        let mut missing = Vec::new();
        if positional.is_empty() {
            missing.push("<from-alias>");
            missing.push("<to-alias>");
        } else {
            missing.push("<to-alias>");
        }
        return missing_required_error(
            &missing,
            &format!("    {} copy <from-alias> <to-alias>", bin),
        );
    }
    if positional.len() > 2 {
        return parse_error(
            &format!(
                "Found argument '{}' which wasn't expected, or isn't valid in this context",
                positional[2]
            ),
            &format!("    {} copy <from-alias> <to-alias>", bin),
        );
    }

    let config_path = match resolve_read_path(global) {
        Ok(path) => path,
        Err(error) => return fail(error),
    };
    let mut config = match read_config(&config_path) {
        Ok(config) => config,
        Err(error) => return fail(error),
    };

    let from_alias = &positional[0];
    let to_alias = &positional[1];
    let script = match config.scripts.get(from_alias) {
        Some(script) => script.clone(),
        None => {
            return fail(CliError::new(format!(
                "AliasNotFound: No script found by alias {}",
                from_alias
            )))
        }
    };

    if config.scripts.contains_key(to_alias) {
        return fail(CliError::new(format!("AliasAlreadyExists:  {}", to_alias)));
    }

    config.scripts.insert(to_alias.clone(), script);
    if let Err(error) = write_config(&config_path, &config) {
        return fail(error);
    }

    println!("Copy from alias {} to new alias {}", from_alias, to_alias);
    0
}

fn run_edit(bin: &str, global: &GlobalOptions, args: &[String]) -> i32 {
