        Err(error) => return fail(error),
    };

    println!("{}", script.command);
    0
}

#[derive(Debug)]
enum ControlAlias {
    Help,
    Version,
    Alias(String),
}

#[derive(Debug)]
enum ControlRun {
    Help,
    Version,
    Alias(String, Vec<String>),
}

fn parse_single_alias_subcommand(
    bin: &str,
    command: &str,
    args: &[String],
) -> Result<ControlAlias, i32> {
    let mut positional = Vec::new();
    for current in args {
        match current.as_str() {
            "-h" | "--help" => return Ok(ControlAlias::Help),
            "-V" | "--version" => return Ok(ControlAlias::Version),
            _ if current.starts_with('-') && current != "-" => {
                return Err(parse_error(
                    &format!(
                        "Found argument '{}' which wasn't expected, or isn't valid in this context",
                        current
                    ),
                    &format!("    {} {} <alias>", bin, command),
                ))
            }
            _ => positional.push(current.clone()),
        }
    }

    if positional.is_empty() {
        return Err(missing_required_error(
            &["<alias>"],
            &format!("    {} {} <alias>", bin, command),
        ));
    }
    if positional.len() > 1 {
        return Err(parse_error(
            &format!(
                "Found argument '{}' which wasn't expected, or isn't valid in this context",
                positional[1]
            ),
            &format!("    {} {} <alias>", bin, command),
        ));
    }

    Ok(ControlAlias::Alias(positional.remove(0)))
}

fn parse_run_like_subcommand(
    bin: &str,
    command: &str,
    args: &[String],
) -> Result<ControlRun, i32> {
    let mut index = 0usize;
    let mut positional = Vec::new();
    let mut raw_mode = false;

    while index < args.len() {
        let current = &args[index];
        if !raw_mode && current == "--" {
            raw_mode = true;
            index += 1;
            continue;
        }

        if !raw_mode {
            match current.as_str() {
                "-h" | "--help" => return Ok(ControlRun::Help),
                "-V" | "--version" => return Ok(ControlRun::Version),
                _ if current.starts_with('-') && current != "-" => {
                    return Err(parse_error(
                        &format!(
                            "Found argument '{}' which wasn't expected, or isn't valid in this context",
                            current
                        ),
                        &format!("    {} {} <alias> [args]...", bin, command),
                    ))
                }
                _ => {}
            }
        }

        positional.push(current.clone());
        index += 1;
    }

    if positional.is_empty() {
        return Err(missing_required_error(
            &["<alias>"],
            &format!("    {} {} <alias> [args]...", bin, command),
        ));
    }

    let alias = positional.remove(0);
    if positional.first().map(String::as_str) == Some("--") {
        positional.remove(0);
    }

    Ok(ControlRun::Alias(alias, positional))
}

fn resolve_read_path(global: &GlobalOptions) -> Result<PathBuf, CliError> {
    if let Some(path) = &global.config_path {
        return Ok(PathBuf::from(path));
    }

    if let Some(path) = env::var_os("PIER_CONFIG_PATH") {
        return Ok(PathBuf::from(path));
    }

    let local = PathBuf::from("pier.toml");
    if local.exists() {
        return Ok(local);
    }

    let mut candidates = Vec::new();
    if let Some(config_home) = config_home_dir() {
        candidates.push(config_home.join("pier").join("config.toml"));
        candidates.push(config_home.join("pier").join("config"));
        candidates.push(config_home.join("pier.toml"));
    }
    if let Some(home) = home_dir() {
        candidates.push(home.join(".pier.toml"));
        candidates.push(home.join(".pier"));
    }

    for candidate in candidates {
        if candidate.exists() {
            return Ok(candidate);
        }
    }

    Err(CliError::new(
        "No default config file found. See help for more info.",
    ))
}

fn resolve_init_path(global: &GlobalOptions) -> PathBuf {
    if let Some(path) = &global.config_path {
        return PathBuf::from(path);
    }

    match config_home_dir() {
        Some(path) => path.join("pier").join("config.toml"),
        None => PathBuf::from(""),
    }
}

fn read_config(path: &Path) -> Result<Config, CliError> {
    let raw = fs::read_to_string(path).map_err(|error| {
        CliError::new(format!(
            "Unable to read config from file {}: {} ",
            path.display(),
            error
        ))
    })?;

    toml::from_str::<Config>(&raw).map_err(|error| {
        CliError::new(format!(
            "Unable to parse toml config from file {}: {}",
            path.display(),
            error
        ))
    })
}

fn write_config(path: &Path, config: &Config) -> Result<(), CliError> {
    let raw = toml::to_string_pretty(config)
        .map_err(|error| CliError::new(format!("Unable to serialize config: {}", error)))?;
    fs::write(path, raw)
        .map_err(|error| CliError::new(format!("Unable to write config to file {}: {}", path.display(), error)))
}

fn lookup_script_with_empty_message<'a>(config: &'a Config, alias: &str) -> Result<&'a Script, CliError> {
    if config.scripts.is_empty() {
        return Err(CliError::new(
            "No scripts exist. Would you like to add a new script?",
        ));
    }

    config
        .scripts
        .get(alias)
        .ok_or_else(|| CliError::new(format!("AliasNotFound: No script found by alias {}", alias)))
}

fn lookup_script_with_empty_message_mut<'a>(
    config: &'a mut Config,
    alias: &str,
) -> Result<&'a mut Script, CliError> {
    if config.scripts.is_empty() {
        return Err(CliError::new(
            "No scripts exist. Would you like to add a new script?",
        ));
    }

    config
        .scripts
        .get_mut(alias)
        .ok_or_else(|| CliError::new(format!("AliasNotFound: No script found by alias {}", alias)))
}

fn run_script(alias: &str, script: &Script, args: &[String], verbose: bool) -> i32 {
    if verbose {
        println!("Starting script \"{}\"", alias);
        println!("{}", RULE);
    }

    let mut command = Command::new("sh");
    command
        .arg("-c")
        .arg(&script.command)
        .arg(alias)
        .args(args)
        .stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit());

    let status = match command.status() {
        Ok(status) => status,
        Err(error) => {
            return fail(CliError::new(format!(
                "Failed to run script {}: {}",
                alias, error
            )))
        }
    };

    if verbose {
        println!("{}", RULE);
        println!("Script complete");
    }

    status.code().unwrap_or(1)
}

fn open_editor(initial: String) -> Result<String, String> {
    let editor = env::var("VISUAL")
        .or_else(|_| env::var("EDITOR"))
        .unwrap_or_else(|_| "vi".to_string());
    let path = temp_edit_path();

    if let Err(error) = fs::write(&path, initial) {
        return Err(format!(
            "Unable to prepare temporary edit buffer {}: {}",
            path.display(),
            error
        ));
    }

    let status = Command::new(&editor).arg(&path).status();
    match status {
        Ok(status) if status.success() => {}
        Ok(_) | Err(_) => {
            let _ = fs::remove_file(&path);
            return Err(format!(
                "EditorError: Failed when trying to get input from editor Failed to open `{}` as a text editor or editor was terminated with errors.",
                editor
            ));
        }
    }

    let updated = fs::read_to_string(&path).map_err(|error| {
        format!(
            "Unable to read edited content from {}: {}",
            path.display(),
            error
        )
    })?;
    let _ = fs::remove_file(&path);
    Ok(updated)
}

fn temp_edit_path() -> PathBuf {
    let base = env::temp_dir();
    let counter = TEMP_COUNTER.fetch_add(1, AtomicOrdering::Relaxed);
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or(0);
    base.join(format!(
        "xvrqt_scrawl_{}_{}_{}",
        process::id(),
        nanos,
        counter
    ))
}

fn collect_scripts_for_list<'a>(
    config: &'a Config,
    filter_tags: Option<&[String]>,
) -> Vec<(&'a String, &'a Script)> {
    match filter_tags {
        None => config.scripts.iter().collect(),
        Some(tags) => {
            let mut rows = Vec::new();
            for tag in tags {
                for (alias, script) in &config.scripts {
                    if script
                        .tags
                        .as_ref()
                        .map(|values| values.iter().any(|value| value == tag))
                        .unwrap_or(false)
                    {
                        rows.push((alias, script));
                    }
                }
            }
            rows
        }
    }
}

#[derive(Debug, Clone, Copy)]
enum CommandDisplay {
    Full,
    Truncated(usize),
}

fn render_list_table(rows: Vec<(&String, &Script)>, display: CommandDisplay) -> String {
    let mut entries = Vec::new();
    for (alias, script) in rows {
        let tags = script
            .tags
            .as_ref()
            .map(|tags| tags.join(","))
            .unwrap_or_default();
        let description = script.description.clone().unwrap_or_default();
        let mut command_lines: Vec<String> = script.command.lines().map(|line| line.to_string()).collect();
        if command_lines.is_empty() {
            command_lines.push(String::new());
        }

        match display {
            CommandDisplay::Full => {
                for (line_index, line) in command_lines.iter().enumerate() {
                    entries.push(ListRow {
                        alias: if line_index == 0 {
                            alias.clone()
                        } else {
                            String::new()
                        },
                        tags: if line_index == 0 {
                            tags.clone()
                        } else {
                            String::new()
                        },
                        command: line.clone(),
                        description: if line_index == 0 {
                            description.clone()
                        } else {
                            String::new()
                        },
                    });
                }
            }
            CommandDisplay::Truncated(width) => {
                let first_line = command_lines.first().cloned().unwrap_or_default();
                let command = first_line.chars().take(width).collect::<String>();
                entries.push(ListRow {
                    alias: alias.clone(),
                    tags,
                    command,
                    description,
                });
            }
        }
    }

    let mut widths = (
        "Alias".chars().count(),
        "Tags".chars().count(),
        "Command".chars().count(),
        "Description".chars().count(),
    );

    for row in &entries {
        widths.0 = widths.0.max(row.alias.chars().count());
        widths.1 = widths.1.max(row.tags.chars().count());
        widths.2 = widths.2.max(row.command.chars().count());
        widths.3 = widths.3.max(row.description.chars().count());
    }

    let header = format_table_row(
        "Alias",
        "Tags",
        "Command",
        "Description",
        widths,
    );
    let rule = TABLE_RULE.to_string().repeat(header.chars().count());

    let mut out = String::new();
    out.push_str(&rule);
    out.push('\n');
    out.push_str(&header);
    out.push('\n');
    out.push_str(&rule);
    out.push('\n');
    for row in entries {
        out.push_str(&format_table_row(
            &row.alias,
            &row.tags,
            &row.command,
            &row.description,
            widths,
        ));
        out.push('\n');
    }
    out.push_str(&rule);
    out.push('\n');
    out
}

#[derive(Debug, Clone)]
struct ListRow {
    alias: String,
    tags: String,
    command: String,
    description: String,
}

fn format_table_row(
    alias: &str,
    tags: &str,
    command: &str,
    description: &str,
    widths: (usize, usize, usize, usize),
) -> String {
    format!(
        "{sep} {alias:<alias_width$} {sep} {tags:<tags_width$} {sep} {command:<command_width$} {sep} {description:<description_width$} {sep}",
        sep = TABLE_SEP,
        alias = alias,
        tags = tags,
        command = command,
        description = description,
        alias_width = widths.0,
        tags_width = widths.1,
        command_width = widths.2,
        description_width = widths.3,
    )
}

fn parse_global_step(args: &[String], state: &mut GlobalState, alias_phase: bool) -> ParseStep {
    if args.is_empty() {
        return ParseStep::Signal(GlobalToken::NotGlobal);
    }

    let current = &args[0];
    match current.as_str() {
        "-h" | "--help" => return ParseStep::Signal(GlobalToken::Help),
        "-V" | "--version" => return ParseStep::Signal(GlobalToken::Version),
        "-v" | "--verbose" => {
            if state.global.verbose {
                state.repeated_verbose = true;
            } else {
                state.global.verbose = true;
            }
            return ParseStep::Consumed(1);
        }
        "-c" | "--config-file" => {
            if args.len() < 2 {
                return ParseStep::MissingValue("--config-file <path>".to_string());
            }
            set_cli_config_path(state, args[1].clone());
            return ParseStep::Consumed(2);
        }
        _ => {}
    }

    if let Some(value) = current.strip_prefix("--config-file=") {
        set_cli_config_path(state, value.to_string());
        return ParseStep::Consumed(1);
    }

    if current.starts_with('-') && current != "-" {
        if current.starts_with("--") {
            return ParseStep::UnknownOption(current.clone());
        }

        let short = &current[1..];
        let mut consumed = 1usize;
        let mut chars = short.chars().peekable();
        while let Some(ch) = chars.next() {
            match ch {
                'h' => return ParseStep::Signal(GlobalToken::Help),
                'V' => return ParseStep::Signal(GlobalToken::Version),
                'v' => {
                    if state.global.verbose {
                        state.repeated_verbose = true;
                    } else {
                        state.global.verbose = true;
                    }
                }
                'c' => {
                    let rest: String = chars.collect();
                    if !rest.is_empty() {
                        set_cli_config_path(state, rest);
                        return ParseStep::Consumed(consumed);
                    }
                    if args.len() < 2 {
                        return ParseStep::MissingValue("--config-file <path>".to_string());
                    }
                    set_cli_config_path(state, args[1].clone());
                    consumed = 2;
                    return ParseStep::Consumed(consumed);
                }
                _ => return ParseStep::UnknownOption(current.clone()),
            }
        }
        return ParseStep::Consumed(consumed);
    }

    if alias_phase {
        ParseStep::Signal(GlobalToken::NotGlobal)
    } else {
        ParseStep::Signal(GlobalToken::NotGlobal)
    }
}

fn set_cli_config_path(state: &mut GlobalState, path: String) {
    if state.global.config_from_cli {
        state.repeated_config = true;
    } else {
        state.global.config_path = Some(path);
        state.global.config_from_cli = true;
    }
}

fn subcommand_from_name(name: &str) -> Option<Subcommand> {
    match name {
        "add" => Some(Subcommand::Add),
        "config-init" | "init" => Some(Subcommand::ConfigInit),
        "copy" | "cp" => Some(Subcommand::Copy),
        "edit" => Some(Subcommand::Edit),
        "help" => Some(Subcommand::Help),
        "list" | "ls" => Some(Subcommand::List),
        "move" | "mv" | "rename" => Some(Subcommand::Move),
        "remove" | "rm" => Some(Subcommand::Remove),
        "run" => Some(Subcommand::Run),
        "show" => Some(Subcommand::Show),
        _ => None,
    }
}

fn canonical_subcommand_name(subcommand: Subcommand) -> &'static str {
    match subcommand {
        Subcommand::Add => "add",
        Subcommand::ConfigInit => "config-init",
        Subcommand::Copy => "copy",
        Subcommand::Edit => "edit",
        Subcommand::Help => "help",
        Subcommand::List => "list",
        Subcommand::Move => "move",
        Subcommand::Remove => "remove",
        Subcommand::Run => "run",
        Subcommand::Show => "show",
    }
}

fn subcommand_suggestion(name: &str, explicit_end: bool) -> Option<String> {
    if explicit_end {
        if let Some(command) = subcommand_from_name(name) {
            return Some(canonical_subcommand_name(command).to_string());
        }
    }

    let candidates = [
        "add",
        "config-init",
        "copy",
        "edit",
        "help",
        "list",
        "move",
        "remove",
        "run",
        "show",
    ];

    let mut best: Option<(&str, i32)> = None;
    for candidate in candidates {
        let prefix = common_prefix_len(name, candidate) as i32;
        let distance = levenshtein(name, candidate) as i32;
        let eligible = prefix >= 3 || distance <= 1 || candidate.starts_with(name) && name.len() >= 2;
        if !eligible {
            continue;
        }
        let score = prefix * 10 - distance * 2 - (name.len() as i32 - candidate.len() as i32).abs();
        match best {
            None => best = Some((candidate, score)),
            Some((_, best_score)) if score > best_score => best = Some((candidate, score)),
            _ => {}
        }
    }
    best.map(|(candidate, _)| candidate.to_string())
}

fn common_prefix_len(left: &str, right: &str) -> usize {
    left.chars()
        .zip(right.chars())
        .take_while(|(a, b)| a == b)
        .count()
}

fn levenshtein(left: &str, right: &str) -> usize {
    let left: Vec<char> = left.chars().collect();
    let right: Vec<char> = right.chars().collect();
    if left.is_empty() {
        return right.len();
    }
    if right.is_empty() {
        return left.len();
    }

    let mut previous: Vec<usize> = (0..=right.len()).collect();
    let mut current = vec![0usize; right.len() + 1];

    for (i, left_char) in left.iter().enumerate() {
        current[0] = i + 1;
        for (j, right_char) in right.iter().enumerate() {
            let cost = usize::from(left_char != right_char);
            current[j + 1] = (current[j] + 1)
                .min(previous[j + 1] + 1)
                .min(previous[j] + cost);
        }
        previous.clone_from(&current);
    }

    previous[right.len()]
}

fn top_usage_for_flags(bin: &str, global: &GlobalOptions) -> String {
    if !global.verbose && !global.config_from_cli {
        return full_top_usage(bin);
    }

    let mut usage = format!("    {} <alias>", bin);
    if global.config_from_cli {
        usage.push_str(" --config-file <path>");
    }
    if global.verbose {
        usage.push_str(" --verbose");
    }
    usage
}

fn full_top_usage(bin: &str) -> String {
    format!(
        "    {} [FLAGS] [OPTIONS] <alias> [args]...\n    {} [FLAGS] [OPTIONS] <SUBCOMMAND>",
        bin, bin
    )
}

fn repeated_verbose_error(bin: &str, global: &GlobalOptions) -> i32 {
    parse_error(
        "The argument '--verbose' was provided more than once, but cannot be used multiple times",
        &top_usage_for_flags(bin, global),
    )
}

fn repeated_config_error(bin: &str, global: &GlobalOptions) -> i32 {
    parse_error(
        "The argument '--config-file <path>' was provided more than once, but cannot be used multiple times",
        &top_usage_for_flags(bin, global),
    )
}

fn unknown_subcommand_error(
    bin: &str,
    global: &GlobalOptions,
    subcommand: &str,
    suggestion: Option<&str>,
) -> i32 {
    eprintln!("error: The subcommand '{}' wasn't recognized", subcommand);
    if let Some(suggestion) = suggestion {
        eprintln!("\tDid you mean '{}'?", suggestion);
        eprintln!();
        eprintln!(
            "If you believe you received this message in error, try re-running with '{} -- {}'",
            bin, subcommand
        );
    }
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("{}", top_usage_for_flags(bin, global));
    eprintln!();
    eprintln!("For more information try --help");
    1
}

fn help_unknown_subcommand_error(bin: &str, subcommand: &str) -> i32 {
    eprintln!("error: The subcommand '{}' wasn't recognized", subcommand);
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("\t{} help <subcommands>...", bin);
    eprintln!();
    eprintln!("For more information try --help");
    1
}

fn missing_required_error(required: &[&str], usage: &str) -> i32 {
    eprintln!("error: The following required arguments were not provided:");
    for item in required {
        eprintln!("    {}", item);
    }
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("{}", usage);
    eprintln!();
    eprintln!("For more information try --help");
    1
}

fn parse_error(message: &str, usage: &str) -> i32 {
    eprintln!("error: {}", message);
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("{}", usage);
    eprintln!();
    eprintln!("For more information try --help");
    1
}

fn fail(error: CliError) -> i32 {
    eprintln!("error: {}", error.message);
    1
}

fn bin_name(args: &[String]) -> String {
    args.first()
        .and_then(|value| Path::new(value).file_name())
        .map(|value| value.to_string_lossy().into_owned())
        .unwrap_or_else(|| "executable".to_string())
}

fn home_dir() -> Option<PathBuf> {
