            raise ParseError(f"unexpected eof encountered at line {line_number}")
        esc = content[i]
        mapping = {
            "b": "\b",
            "t": "\t",
            "n": "\n",
            "f": "\f",
            "r": "\r",
            '"': '"',
            "\\": "\\",
        }
        out.append(mapping.get(esc, esc))
        i += 1
    return "".join(out)


def parse_string_value(lines: list[str], index: int, raw_value: str) -> tuple[str, int]:
    stripped = raw_value.strip()
    line_number = index + 1

    if stripped.startswith("'''"):
        if stripped.endswith("'''") and len(stripped) >= 6:
            return stripped[3:-3], index

        content = stripped[3:]
        content_lines: list[str] = []
        if content:
            content_lines.append(content)
        i = index + 1
        while i < len(lines):
            line = lines[i]
            end = line.find("'''")
            if end != -1:
                content_lines.append(line[:end])
                if content_lines and content_lines[0] == "":
                    content_lines = content_lines[1:]
                return "\n".join(content_lines), i
            content_lines.append(line)
            i += 1
        raise ParseError(f"unexpected eof encountered at line {line_number}")

    if stripped.startswith("'") and stripped.endswith("'") and len(stripped) >= 2:
        return stripped[1:-1], index

    if stripped.startswith('"') and stripped.endswith('"') and len(stripped) >= 2:
        return unescape_basic_string(stripped[1:-1], line_number), index

    raise ParseError(f"unexpected token encountered at line {line_number}")


def parse_tag_array(lines: list[str], index: int, raw_value: str) -> tuple[list[str], int]:
    stripped = raw_value.strip()
    line_number = index + 1

    if not stripped.startswith("["):
        raise ParseError(f"unexpected token encountered at line {line_number}")

    if stripped.endswith("]"):
        inner = stripped[1:-1].strip()
        if not inner:
            return [], index
        parts = [part.strip() for part in inner.split(",") if part.strip()]
        tags = []
        for part in parts:
            value, _ = parse_string_value([f"={part}"], 0, part)
            tags.append(value)
        return tags, index

    tags: list[str] = []
    i = index + 1
    while i < len(lines):
        line = lines[i].strip()
        if line == "]":
            return tags, i
        if not line:
            i += 1
            continue
        if line.endswith(","):
            line = line[:-1].rstrip()
        value, _ = parse_string_value([f"={line}"], 0, line)
        tags.append(value)
        i += 1
    raise ParseError(f"unexpected eof encountered at line {line_number}")


def parse_config_text(text: str) -> ConfigData:
    lines = text.splitlines()
    config = ConfigData()
    current_alias: str | None = None

    i = 0
    while i < len(lines):
        raw_line = lines[i]
        stripped = raw_line.strip()

        if not stripped or stripped.startswith("#"):
            i += 1
            continue

        if stripped.startswith("[") and stripped.endswith("]"):
            header = stripped[1:-1].strip()
            if header == "default":
                current_alias = None
            elif header.startswith("scripts."):
                current_alias = header[len("scripts.") :]
                config.scripts.setdefault(current_alias, ScriptEntry())
            else:
                current_alias = None
            i += 1
            continue

        if current_alias is None:
            i += 1
            continue

        if "=" not in raw_line:
            raise ParseError(f"unexpected token encountered at line {i + 1}")

        key, value = raw_line.split("=", 1)
        key = key.strip()
        entry = config.scripts[current_alias]

        if key == "command":
            parsed, i = parse_string_value(lines, i, value)
            entry.command = parsed
        elif key == "description":
            parsed, i = parse_string_value(lines, i, value)
            entry.description = parsed
        elif key == "tags":
            parsed, i = parse_tag_array(lines, i, value)
            entry.tags = parsed
        i += 1

    return config


def format_toml_string(value: str) -> str:
    if "'''" in value:
        escaped = (
            value.replace("\\", "\\\\")
            .replace('"', '\\"')
            .replace("\n", "\\n")
            .replace("\r", "\\r")
            .replace("\t", "\\t")
        )
        return f'"{escaped}"'
    if "\n" in value:
        return "'''\n" + value + "'''"
    if "'" in value:
        return "'''" + value + "'''"
    return "'" + value + "'"


def dump_config(config: ConfigData) -> str:
    parts: list[str] = []
    for alias in sorted(config.scripts):
        entry = config.scripts[alias]
        parts.append(f"[scripts.{alias}]")
        parts.append(f"command = {format_toml_string(entry.command)}")
        if entry.description is not None:
            parts.append(f"description = {format_toml_string(entry.description)}")
        if entry.tags:
            parts.append("tags = [")
            for tag in entry.tags:
                parts.append(f"    {format_toml_string(tag)},")
            parts.append("]")
        parts.append("")
    parts.append("[default]")
    return "\n".join(parts) + "\n"


def config_dir_base() -> str | None:
    xdg = os.environ.get("XDG_CONFIG_HOME")
    if xdg:
        return xdg
    home = os.environ.get("HOME")
    if home:
        return str(Path(home) / ".config")
    return None


def resolve_config_for_read(explicit_path: str | None) -> str | None:
    if explicit_path is not None:
        return explicit_path
    if "PIER_CONFIG_PATH" in os.environ:
        return os.environ.get("PIER_CONFIG_PATH", "")
    if path_exists("pier.toml"):
        return "pier.toml"
    base = config_dir_base()
    candidates: list[str] = []
    if base is not None:
        candidates.extend(
            [
                str(Path(base) / "pier" / "config.toml"),
                str(Path(base) / "pier" / "config"),
                str(Path(base) / "pier.toml"),
            ]
        )
    home = os.environ.get("HOME")
    if home:
        candidates.extend([str(Path(home) / ".pier.toml"), str(Path(home) / ".pier")])
    for candidate in candidates:
        if path_exists(candidate):
            return candidate
    return None


def resolve_config_for_init(explicit_path: str | None) -> tuple[str | None, bool]:
    if explicit_path is not None:
        return explicit_path, True
    if "PIER_CONFIG_PATH" in os.environ:
        return os.environ.get("PIER_CONFIG_PATH", ""), True
    if path_exists("pier.toml"):
        return "pier.toml", False
    base = config_dir_base()
    if base is None:
        return None, False
    return str(Path(base) / "pier" / "config.toml"), False


def load_config(explicit_path: str | None) -> tuple[ConfigData | None, str | None, int | None]:
    path = resolve_config_for_read(explicit_path)
    if path is None:
        return None, None, error_no_default_config()
    try:
        text = read_text_file(path)
    except OSError as exc:
        return None, path, error_read_config(path, exc)
    try:
        return parse_config_text(text), path, None
    except ParseError as exc:
        return None, path, error_parse_config(path, str(exc))


def save_config(path: str, config: ConfigData) -> int | None:
    try:
        write_text_file(path, dump_config(config))
    except OSError as exc:
        return error_write_config(path, exc)
    return None


def edit_via_editor(initial_content: str) -> tuple[str | None, int | None]:
    editor = os.environ.get("EDITOR") or "vi"
    fd, path = tempfile.mkstemp(prefix="xvrqt_scrawl_", suffix="_0")
    os.close(fd)
    tmp_path = Path(path)
    try:
        tmp_path.write_text(initial_content, encoding="utf-8")
        try:
            result = subprocess.run(shlex.split(editor) + [str(tmp_path)])
        except OSError:
            return None, error_editor(editor)
        if result.returncode != 0:
            return None, error_editor(editor)
        return tmp_path.read_text(encoding="utf-8"), None
    finally:
        try:
            tmp_path.unlink()
        except OSError:
            pass


def list_matches(config: ConfigData, filter_tags: list[str], tag_filter_present: bool) -> list[tuple[str, ScriptEntry]]:
    aliases = sorted(config.scripts)
    if not tag_filter_present:
        return [(alias, config.scripts[alias]) for alias in aliases]
    matches: list[tuple[str, ScriptEntry]] = []
    for tag in filter_tags:
        for alias in aliases:
            entry = config.scripts[alias]
            if tag in entry.tags:
                matches.append((alias, entry))
    return matches


def table_output(rows: list[tuple[str, str, str, str]]) -> str:
    headers = ("Alias", "Tags", "Command", "Description")
    widths = [
        max(len(headers[0]), *(len(row[0]) for row in rows)),
        max(len(headers[1]), *(len(row[1]) for row in rows)),
        max(len(headers[2]), *(len(row[2]) for row in rows)),
        max(len(headers[3]), *(len(row[3]) for row in rows)),
    ]
    border = "≖" * (sum(widths) + 13)

    def format_row(values: tuple[str, str, str, str]) -> str:
        return (
            f"⋮ {values[0].ljust(widths[0])} "
            f"⋮ {values[1].ljust(widths[1])} "
            f"⋮ {values[2].ljust(widths[2])} "
            f"⋮ {values[3].ljust(widths[3])} ⋮"
        )

    lines = [border, format_row(headers), border]
    lines.extend(format_row(row) for row in rows)
    lines.append(border)
    return "\n".join(lines) + "\n"


def render_list(entries: list[tuple[str, ScriptEntry]], alias_only: bool, full: bool, cmd_width: int | None) -> str:
    if alias_only:
        return "".join(f"{alias}\n" for alias, _entry in entries)

    rows: list[tuple[str, str, str, str]] = []
    for alias, entry in entries:
        tags = ",".join(entry.tags)
        description = entry.description or ""
        lines = entry.command.splitlines() or [""]
        if full:
            for idx, command_line in enumerate(lines):
                rows.append(
                    (
                        alias if idx == 0 else "",
                        tags if idx == 0 else "",
                        command_line,
                        description if idx == 0 else "",
                    )
                )
        else:
            preview = lines[0]
            if cmd_width is not None:
                preview = preview[: max(cmd_width, 0)]
            rows.append((alias, tags, preview, description))

    if not rows:
        return ""
    return table_output(rows)


def run_entry(alias: str, entry: ScriptEntry, args: list[str]) -> int:
    completed = subprocess.run(["sh", "-c", entry.command, alias, *args])
    return completed.returncode


def handle_config_init(config_path: str | None) -> int:
    target, explicit = resolve_config_for_init(config_path)
    if target is None:
        return error_create_directory(FileNotFoundError(2, os.strerror(2)))
    if not explicit and target == "pier.toml" and path_exists(target):
        return error_cannot_init(target)
    if explicit and path_exists(target):
        return error_cannot_init(target)
    if not explicit and target == "pier.toml":
        return error_cannot_init(target)

    parent_str: str | None
    if target == "":
        parent_str = None
    else:
        parent_str = os.path.dirname(target)
    if parent_str is not None and not path_exists(parent_str):
        try:
            os.mkdir(parent_str)
        except OSError as exc:
            return error_create_directory(exc)

    if path_exists(target):
        return error_cannot_init(target)

    stdout("Added hello-pier")
    config = ConfigData(
        scripts={
            "hello-pier": ScriptEntry(
                command="echo Hello, Pier!",
                description="This is an example command.",
            )
        }
    )
    return save_config(target, config) or 0


def parse_add(args: list[str], config_path: str | None) -> int:
    force = False
    alias: str | None = None
    description: str | None = None
    tags: list[str] = []
    command: str | None = None
    i = 0

    while i < len(args):
        token = args[i]
        if token in ("-h", "--help"):
            stdout(ADD_HELP)
            return 0
        if token in ("-V", "--version"):
            stdout(VERSION_BY_CANONICAL["add"])
            return 0
        if token == "--":
            remainder = args[i + 1 :]
            if len(remainder) > 1:
                return error_unknown_arg(remainder[1], "executable add [FLAGS] [OPTIONS] --alias <alias> [--] [command]")
            if remainder:
                command = remainder[0]
            break
        if token in ("-f", "--force"):
            force = True
            i += 1
            continue
        if token in ("-a", "--alias"):
            if i + 1 >= len(args):
                return error_missing_value("--alias <alias>", "executable add [FLAGS] [OPTIONS] --alias <alias> [--] [command]")
            alias = args[i + 1]
            i += 2
            continue
        if token in ("-d", "--description"):
            if i + 1 >= len(args):
                return error_missing_value("--description <description>", "executable add [FLAGS] [OPTIONS] --alias <alias> [--] [command]")
            description = args[i + 1]
            i += 2
            continue
        if token in ("-t", "--tag"):
            i += 1
            while i < len(args) and not args[i].startswith("-"):
                tags.append(args[i])
                i += 1
            continue
        if token.startswith("-"):
            return error_unknown_arg(token, "executable add [FLAGS] [OPTIONS] --alias <alias> [--] [command]")
        if command is not None:
            return error_unknown_arg(token, "executable add [FLAGS] [OPTIONS] --alias <alias> [--] [command]")
        command = token
        i += 1
        if i < len(args):
            return error_unknown_arg(args[i], "executable add [FLAGS] [OPTIONS] --alias <alias> [--] [command]")

    if alias is None:
        return error_required(["--alias <alias>"], "executable add [FLAGS] [OPTIONS] --alias <alias> [--] [command]")

    if command is None:
        command, err = edit_via_editor("")
        if err is not None:
            return err

    config, path, err = load_config(config_path)
    if err is not None or config is None or path is None:
        return err or 1

    if alias in config.scripts and not force:
        return 1

    config.scripts[alias] = ScriptEntry(command=command, description=description, tags=list(tags))
    err = save_config(path, config)
    if err is not None:
        return err
    stdout(f"Added {alias}")
    return 0


def parse_list(args: list[str], config_path: str | None) -> int:
    alias_only = False
    full = False
    cmd_width: int | None = None
    filter_tags: list[str] = []
    tag_filter_present = False
    i = 0

    while i < len(args):
        token = args[i]
        if token in ("-h", "--help"):
            stdout(LIST_HELP)
            return 0
        if token in ("-V", "--version"):
            stdout(VERSION_BY_CANONICAL["list"])
            return 0
        if token in ("-q", "--list_aliases"):
            alias_only = True
            i += 1
            continue
        if token in ("-l", "--cmd_full"):
            full = True
            i += 1
            continue
        if token in ("-c", "--cmd_width"):
            if i + 1 >= len(args):
                return error_missing_value("--cmd_width <cmd-width>", "executable list --cmd_width <cmd-width>")
            try:
                cmd_width = int(args[i + 1], 10)
            except ValueError:
                return error_invalid_cmd_width()
            i += 2
            continue
        if token in ("-t", "--tag"):
            tag_filter_present = True
            i += 1
            while i < len(args) and not args[i].startswith("-"):
                filter_tags.append(args[i])
                i += 1
            continue
        return error_unknown_arg(token, "executable list [FLAGS] [OPTIONS]")

    config, _path, err = load_config(config_path)
    if err is not None or config is None:
        return err or 1
    if not config.scripts:
        return error_no_scripts()

    entries = list_matches(config, filter_tags, tag_filter_present)
    output = render_list(entries, alias_only=alias_only, full=full, cmd_width=None if full else cmd_width)
    if output:
        sys.stdout.write(output)
    return 0


def parse_run(args: list[str], config_path: str | None) -> int:
    if not args:
        return error_required(["<alias>"], "executable run <alias> [args]...")
    if args[0] in ("-h", "--help"):
        stdout(RUN_HELP)
        return 0
    if args[0] in ("-V", "--version"):
        stdout(VERSION_BY_CANONICAL["run"])
        return 0

    alias = args[0]
    run_args: list[str] = []

Chunk ID: d22c9e
Wall time: 0.0000 seconds
Process exited with code 0
Original token count: 3157
Output:
    i = 1
    while i < len(args):
        token = args[i]
        if token == "--":
            run_args.extend(args[i + 1 :])
            break
        if token.startswith("-"):
            return error_unknown_arg(token, "executable run <alias> [args]...")
        run_args.append(token)
        i += 1

    config, _path, err = load_config(config_path)
    if err is not None or config is None:
        return err or 1
    entry = config.scripts.get(alias)
    if entry is None:
        return error_alias_not_found(alias)
    return run_entry(alias, entry, run_args)


def parse_show(args: list[str], config_path: str | None) -> int:
