def parse_copy(args: list[str], config_path: str | None) -> int:
    if not args:
        return error_required(["<from-alias>", "<to-alias>"], "executable copy <from-alias> <to-alias>")
    if args[0] in ("-h", "--help"):
        stdout(COPY_HELP)
        return 0
    if args[0] in ("-V", "--version"):
        stdout(VERSION_BY_CANONICAL["copy"])
        return 0
    if len(args) < 2:
        return error_required(["<from-alias>", "<to-alias>"], "executable copy <from-alias> <to-alias>")
    from_alias, to_alias = args[0], args[1]
    if len(args) > 2:
        return error_unknown_arg(args[2], "executable copy <from-alias> <to-alias>")

    config, path, err = load_config(config_path)
    if err is not None or config is None or path is None:
        return err or 1
    entry = config.scripts.get(from_alias)
    if entry is None:
        return error_alias_not_found(from_alias)
    if from_alias == to_alias:
        return error_alias_already_exists(to_alias)
    if to_alias in config.scripts:
        return 1
    config.scripts[to_alias] = ScriptEntry(command=entry.command, description=entry.description, tags=list(entry.tags))
    err = save_config(path, config)
    return err or 0


def parse_move(args: list[str], config_path: str | None) -> int:
    force = False
    positionals: list[str] = []
    i = 0
    while i < len(args):
        token = args[i]
        if token in ("-h", "--help"):
            stdout(MOVE_HELP)
            return 0
        if token in ("-V", "--version"):
            stdout(VERSION_BY_CANONICAL["move"])
            return 0
        if token in ("-f", "--force"):
            force = True
            i += 1
            continue
        if token.startswith("-"):
            return error_unknown_arg(token, "executable move [FLAGS] <from-alias> <to-alias>")
        positionals.append(token)
        i += 1

    if len(positionals) < 2:
        return error_required(["<from-alias>", "<to-alias>"], "executable move [FLAGS] <from-alias> <to-alias>")
    if len(positionals) > 2:
        return error_unknown_arg(positionals[2], "executable move [FLAGS] <from-alias> <to-alias>")

    from_alias, to_alias = positionals
    config, path, err = load_config(config_path)
    if err is not None or config is None or path is None:
        return err or 1
    entry = config.scripts.get(from_alias)
    if entry is None:
        return error_alias_not_found(from_alias)
    if from_alias == to_alias:
        if not force:
            return error_alias_already_exists(to_alias)
        stdout(f"Move from alias {from_alias} to new alias {to_alias}")
        return 0
    if to_alias in config.scripts and not force:
        return 1
    config.scripts[to_alias] = ScriptEntry(command=entry.command, description=entry.description, tags=list(entry.tags))
    if from_alias in config.scripts:
        del config.scripts[from_alias]
    err = save_config(path, config)
    if err is not None:
        return err
    stdout(f"Move from alias {from_alias} to new alias {to_alias}")
    return 0


def parse_edit(args: list[str], config_path: str | None) -> int:
    if not args:
        return error_required(["<alias>"], "executable edit <alias>")
