def parse_help(args: list[str]) -> int:
    if not args:
        stdout(ROOT_HELP_SHORT)
        return 0
    first = args[0]
    canonical = SUBCOMMAND_ALIASES.get(first)
    if canonical is None:
        return error_unknown_subcommand(first, None, "")
    if canonical == "help":
        if len(args) == 1:
            stdout(HELP_HELP)
            return 0
        return error_unknown_subcommand(args[1], None, "")
    if len(args) > 1:
        return error_unknown_subcommand(args[1], None, "")
    stdout(HELP_BY_CANONICAL[canonical])
    return 0


def dispatch_subcommand(name: str, args: list[str], config_path: str | None) -> int:
    canonical = SUBCOMMAND_ALIASES[name]
    if canonical == "add":
        return parse_add(args, config_path)
    if canonical == "config-init":
        if args and args[0] in ("-h", "--help"):
            stdout(CONFIG_INIT_HELP)
            return 0
        if args and args[0] in ("-V", "--version"):
            stdout(VERSION_BY_CANONICAL["config-init"])
            return 0
        if args:
            return error_unknown_arg(args[0], "executable config-init")
        return handle_config_init(config_path)
    if canonical == "copy":
        return parse_copy(args, config_path)
    if canonical == "edit":
        return parse_edit(args, config_path)
    if canonical == "help":
        return parse_help(args)
    if canonical == "list":
        return parse_list(args, config_path)
    if canonical == "move":
        return parse_move(args, config_path)
    if canonical == "remove":
        return parse_remove(args, config_path)
    if canonical == "run":
        return parse_run(args, config_path)
    if canonical == "show":
        return parse_show(args, config_path)
    return 1


def root_usage_for_alias(config_before_alias: bool, config_present: bool) -> str:
    if config_before_alias or config_present:
        return "executable <alias> --config-file <path>"
    return "executable [FLAGS] [OPTIONS] <alias> [args]...\n    executable [FLAGS] [OPTIONS] <SUBCOMMAND>"


def run_root_alias(alias: str, alias_args: list[str], config_path: str | None, config_before_alias: bool) -> int:
    suggestion = subcommand_suggestion(alias)
    if suggestion is not None:
        return error_unknown_subcommand(alias, suggestion, root_usage_for_alias(config_before_alias, False))

    config, _path, err = load_config(config_path)
    if err is not None or config is None:
        return err or 1
    entry = config.scripts.get(alias)
    if entry is None:
        return error_alias_not_found(alias)
    return run_entry(alias, entry, alias_args)


def main(argv: list[str]) -> int:
    if not argv:
        return error_required(
            ["<alias>"],
            "executable [FLAGS] [OPTIONS] <alias> [args]...\n    executable [FLAGS] [OPTIONS] <SUBCOMMAND>",
        )

    config_path: str | None = None
    config_before_alias = False
    verbose = False
    help_style: str | None = None
    version_requested = False

    i = 0
    forced_alias_mode = False
    while i < len(argv):
        token = argv[i]
        if token == "--":
            forced_alias_mode = True
            i += 1
            break
        if token in ("-h", "--help"):
            help_style = "long" if token == "--help" else "short"
            i += 1
            continue
        if token in ("-V", "--version"):
            version_requested = True
            i += 1
            continue
        if token in ("-v", "--verbose"):
            verbose = True
            i += 1
            continue
        if token in ("-c", "--config-file"):
            if i + 1 >= len(argv):
                return error_missing_value(
                    "--config-file <path>",
                    "executable [FLAGS] [OPTIONS] <alias> [args]...\n    executable [FLAGS] [OPTIONS] <SUBCOMMAND>",
                )
            config_path = argv[i + 1]
            config_before_alias = True
            i += 2
            continue
        if token.startswith("-"):
            return error_unknown_arg(
                token,
                "executable [FLAGS] [OPTIONS] <alias> [args]...\n    executable [FLAGS] [OPTIONS] <SUBCOMMAND>",
            )
        break

    _ = verbose

    if i >= len(argv):
        if help_style == "long":
            stdout(ROOT_HELP_LONG)
            return 0
        if help_style == "short":
            stdout(ROOT_HELP_SHORT)
            return 0
        if version_requested:
            stdout(ROOT_VERSION)
            return 0
        return error_required(
            ["<alias>"],
            "executable [FLAGS] [OPTIONS] <alias> [args]...\n    executable [FLAGS] [OPTIONS] <SUBCOMMAND>",
        )

    candidate = argv[i]
    remaining = argv[i + 1 :]

    if not forced_alias_mode and candidate in SUBCOMMAND_ALIASES:
        return dispatch_subcommand(candidate, remaining, config_path)

    alias_args: list[str] = []
    j = 0
    while j < len(remaining):
        token = remaining[j]
        if not alias_args and token in ("-h", "--help"):
            help_style = "long" if token == "--help" else "short"
            j += 1
            continue
        if not alias_args and token in ("-V", "--version"):
            version_requested = True
            j += 1
            continue
        if not alias_args and token in ("-v", "--verbose"):
            j += 1
            continue
        if not alias_args and token in ("-c", "--config-file"):
            if j + 1 >= len(remaining):
                return error_missing_value("--config-file <path>", root_usage_for_alias(config_before_alias, True))
            config_path = remaining[j + 1]
            j += 2
            continue
        if token == "--":
            alias_args.extend(remaining[j + 1 :])
            break
        if alias_args:
            if token == "--help":
                return error_unknown_subcommand(token, "help", root_usage_for_alias(config_before_alias, config_path is not None))
            alias_args.append(token)
            j += 1
            continue
        if token.startswith("-"):
            return error_unknown_arg(token, root_usage_for_alias(config_before_alias, config_path is not None))
        alias_args.append(token)
        j += 1

    if help_style == "long":
        stdout(ROOT_HELP_LONG)
        return 0
    if help_style == "short":
        stdout(ROOT_HELP_SHORT)
        return 0
    if version_requested:
        stdout(ROOT_VERSION)
        return 0

    return run_root_alias(candidate, alias_args, config_path, config_before_alias)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

